# These side stations follow the high-W and low-W arcs in the actual temple cuts.
# The Vision apex U values are inset from the scanned surface by the swept half-width,
# keeping the finished flange inside the measured 161.47 mm envelope.


def _profile_wire(station):
    u, points = station
    return Wire.make_polygon([(u, v, w) for v, w in points], close=True)


def _station_loft(profiles):
    return Solid.make_loft([_profile_wire(profile) for profile in profiles], ruled=True).clean()


def _closed_bezier_edges(points):
    handles = []
    for index, point in enumerate(points):
        before = points[index - 1]
        after = points[(index + 1) % len(points)]
        tangent = (after - before).normalized()
        reach = min((point - before).length, (after - point).length) / 3.0
        handles.append(tangent * reach)

    edges = []
    for index, start in enumerate(points):
        finish_index = (index + 1) % len(points)
        finish = points[finish_index]
        edges.append(
            Edge.make_bezier(
                start,
                start + handles[index],
                finish - handles[finish_index],
                finish,
            )
        )
    return edges


def _closed_bezier_path(points):
    return Wire(_closed_bezier_edges(points))


def _rail_sweep(centers, width, depth, offset, surface_at_high_w=False):
    half_width = width / 2.0
    half_depth = depth / 2.0
    points = []
    for u, v, w in centers:
        center_w = w - half_depth if surface_at_high_w else w
        points.append(Vector(u, v, center_w + offset))

    path = _closed_bezier_path(points)
    tangent = path.tangent_at(0)
    section_v = (Vector(0, 1, 0) - tangent * Vector(0, 1, 0).dot(tangent)).normalized() * half_width
    section_w = tangent.cross(section_v).normalized() * half_depth
    if section_w.dot(Vector(0, 0, 1)) < 0:
        section_w = -section_w
    origin = points[0]
    section = Face(
        Wire.make_polygon(
            [
                origin - section_v - section_w,
                origin + section_v - section_w,
                origin + section_v + section_w,
                origin - section_v + section_w,
            ],
            close=True,
        )
    )

    # build123d's Vector sweep mode uses a fixed trihedron. The fixed-binormal OCP
    # overload keeps W aligned around this closed path and produces a real solid.
    sweep = BRepOffsetAPI_MakePipeShell(path.wrapped)
    sweep.SetMode(gp_Dir(0, 0, 1))
    sweep.Add(section.outer_wire().wrapped, False, True)
    sweep.Build()
    if not sweep.IsDone():
        raise RuntimeError("Unable to sweep the closed mating rim")
    sweep.MakeSolid()
    return Solid(sweep.Shape())


def light_seal_components(
    vision_flange_offset_mm=0.0,
    cushion_rail_offset_mm=0.0,
    interface_rail_depth_mm=0.8,
):
    """Build the six editable regions of the simplified rigid Light Seal shell."""
    if not 0.5 <= interface_rail_depth_mm <= 1.0:
        reject("Interface relief must remain between 0.5 and 1.0 mm.", "interface_rail_depth_mm")

    lower = _station_loft(LOWER_PROFILES)
    upper = _station_loft(UPPER_PROFILES)
    left = _station_loft(LEFT_BRIDGE_PROFILES)
    right = _station_loft(RIGHT_BRIDGE_PROFILES)

    # The scan resolves both connections as shallow continuous rails. These named
    # components deliberately overlap the shell by their relief depth so they remain
    # independently visible without introducing a fragile zero-thickness join.
    vision_loop = (*VISION_LOWER, *VISION_RIGHT_SIDE, *reversed(VISION_UPPER), *VISION_LEFT_SIDE)
    cushion_loop = (*CUSHION_LOWER, *CUSHION_RIGHT_SIDE, *reversed(CUSHION_UPPER), *CUSHION_LEFT_SIDE)
    vision = _rail_sweep(vision_loop, 3.8, interface_rail_depth_mm, vision_flange_offset_mm)
    cushion = _rail_sweep(cushion_loop, 3.4, 3.2, cushion_rail_offset_mm, surface_at_high_w=True)

    return (
        ("lower shell", lower),
        ("upper shell and hard nose saddle", upper),
        ("left side bridge", left),
        ("right side bridge", right),
        ("vision_pro_flange", vision),
        ("cushion_rail", cushion),
    )


def light_seal_geometry(
    vision_flange_offset_mm=0.0,
    cushion_rail_offset_mm=0.0,
    interface_rail_depth_mm=0.8,
):
    """Return the complete six-solid reconstruction as one CAD compound."""
    regions = light_seal_components(
        vision_flange_offset_mm=vision_flange_offset_mm,
        cushion_rail_offset_mm=cushion_rail_offset_mm,
        interface_rail_depth_mm=interface_rail_depth_mm,
    )
    solids = []
    for name, region in regions:
        region.label = name
        solids.append(region)
    return Compound(children=solids)
